package it.financemanager.infrastructure.security;import com.fasterxml.jackson.databind.ObjectMapper;import it.financemanager.infrastructure.persistence.repository.UserJpaRepository;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;@Configuration @EnableConfigurationProperties(JwtProperties.class)public class SecurityConfig{@Bean UserDetailsService userDetailsService(UserJpaRepository r){return email->r.findByEmailIgnoreCase(email).map(u->User.withUsername(u.email).password(u.password).roles(u.role.code).build()).orElseThrow(()->new UsernameNotFoundException("Invalid credentials"));}@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}@Bean SecurityFilterChain chain(HttpSecurity h,JwtAuthenticationFilter f,ObjectMapper m)throws Exception{h.csrf(x->x.disable()).cors(x->{}).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(x->x.requestMatchers("/api/v1/auth/**","/v3/api-docs/**","/swagger-ui/**").permitAll().anyRequest().authenticated()).exceptionHandling(x->x.authenticationEntryPoint((q,s,e)->{s.setStatus(401);s.setContentType(MediaType.APPLICATION_PROBLEM_JSON_VALUE);m.writeValue(s.getOutputStream(),ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,"Authentication is required"));})).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class);return h.build();}}
